SELECT fn_cp_import_case('biens-cambriolage-decouverte-au-retour', '{"slug": "biens-cambriolage-decouverte-au-retour", "title": "Ils rentrent de week-end et la porte-fenêtre est ouverte", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Un couple rentrant d''un week-end vous appelle depuis le trottoir devant leur pavillon, découvrant la porte-fenêtre arrière grande ouverte et des désordres visibles depuis l''extérieur, sans avoir pénétré à l''intérieur. Cette découverte, aussi inquiétante soit-elle, s''accompagne d''une incertitude totale sur la présence éventuelle des auteurs à l''intérieur du logement au moment de votre arrivée.\n\nCe couple, pressé par l''inquiétude de constater l''ampleur des dégâts et l''éventuelle disparition d''objets auxquels il tient, souhaite entrer immédiatement dans son propre domicile, cette urgence émotionnelle entrant en tension directe avec la nécessité de sécuriser les lieux avant toute pénétration.\n\nCette situation impose de concilier la légitime impatience de ces occupants avec les impératifs de sécurité et de préservation des traces qui doivent impérativement primer avant toute entrée dans ce logement potentiellement encore occupé par les auteurs.", "questions": [{"position": 1, "max_points": 5, "label": "Comment empêchez-vous ce couple d''entrer immédiatement dans son logement malgré son impatience légitime ?", "hint": "L''entrée précipitée des occupants comporte un risque réel si les auteurs sont encore présents et compromettrait par ailleurs les traces à préserver.", "perfect": "J''explique clairement à ce couple pourquoi je dois vérifier l''absence de danger avant toute entrée, cette explication rendant plus acceptable la frustration que peut engendrer cette attente imposée.\n\nJe reste ferme sur cette interdiction temporaire d''entrer, le risque que les auteurs soient encore présents à l''intérieur constituant un danger réel qui doit primer sur leur impatience de constater les dégâts.\n\nJe reste attentive à leur état émotionnel durant cette attente, cette découverte constituant une épreuve difficile qui mérite une present rassurante malgré la fermeté nécessaire sur l''accès au logement.\n\nJe les tiens informés de chaque étape de la sécurisation, cette transparence sur le déroulement de mon intervention rendant cette attente plus supportable pour ce couple impatient.", "points": [{"position": 1, "label": "Expliquer clairement pourquoi une vérification préalable est nécessaire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rendre l''attente acceptable par l''explication.", "groups": [{"position": 1, "keywords": ["explication claire", "vérification préalable", "attente acceptable"]}]}, {"position": 2, "label": "Rester ferme sur l''interdiction temporaire d''entrer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Risque de présence des auteurs primant sur l''impatience.", "groups": [{"position": 1, "keywords": ["fermeté maintenue", "risque de présence", "priorité sécurité"]}]}, {"position": 3, "label": "Rester attentive à leur état émotionnel durant l''attente", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Présence rassurante malgré la fermeté nécessaire.", "groups": [{"position": 1, "keywords": ["état émotionnel", "présence rassurante", "épreuve difficile"]}]}, {"position": 4, "label": "Tenir informés de chaque étape de la sécurisation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence rendant l''attente plus supportable.", "groups": [{"position": 1, "keywords": ["information continue", "transparence", "attente supportable"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment procédez-vous à la vérification de l''absence des auteurs tout en préservant les traces exploitables ?", "hint": "La sécurisation du logement doit être menée avec méthode, en minimisant l''impact sur les traces qui pourraient être exploitées ultérieurement.", "perfect": "Je procède à une vérification méthodique des différentes pièces du logement, cette sécurisation restant prioritaire avant toute autre considération relative aux constatations à venir.\n\nJe reste attentive à limiter mes déplacements et mes contacts avec les surfaces durant cette vérification, cette précaution étant nécessaire pour ne pas compromettre les traces qui pourront être exploitées par la suite.\n\nJe consigne mentalement les éléments significatifs que je constate durant cette vérification, cette observation immédiate pouvant orienter utilement les constatations formelles qui suivront.\n\nJe sollicite si nécessaire un renfort pour sécuriser efficacement l''ensemble du logement, cette méthode collective étant plus sûre qu''une vérification menée seule dans ces circonstances incertaines.", "points": [{"position": 1, "label": "Procéder à une vérification méthodique des différentes pièces", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Sécurisation prioritaire avant toute autre considération.", "groups": [{"position": 1, "keywords": ["vérification méthodique", "sécurisation prioritaire", "pièces vérifiées"]}]}, {"position": 2, "label": "Limiter les déplacements et contacts pour préserver les traces", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précaution nécessaire pour les traces exploitables.", "groups": [{"position": 1, "keywords": ["déplacements limités", "traces préservées", "précaution nécessaire"]}]}, {"position": 3, "label": "Consigner mentalement les éléments significatifs constatés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orienter utilement les constatations formelles.", "groups": [{"position": 1, "keywords": ["éléments consignés", "observation immédiate", "constatations orientées"]}]}, {"position": 4, "label": "Solliciter un renfort pour sécuriser efficacement le logement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Méthode collective plus sûre que seule.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "méthode collective", "sécurisation efficace"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite des constatations une fois le logement sécurisé et vidé de tout danger ?", "hint": "Une fois la sécurité établie, les constatations doivent être menées méthodiquement, avec l''implication mesurée des occupants.", "perfect": "J''informe le couple que le logement est désormais sécurisé, cette annonce marquant la fin de l''attente imposée et le début d''une phase de constatations méthodiques.\n\nJe les autorise à entrer en les accompagnant, cette présence permettant de canaliser leurs déplacements pour ne pas compromettre les traces encore présentes sur les lieux.\n\nJe recueille leurs premières observations sur les éventuels objets disparus ou déplacés, ces informations étant précieuses pour orienter la suite des constatations techniques.\n\nJe les informe des suites de cette procédure, notamment la nécessité de dresser un inventaire précis des objets dérobés pour la suite du traitement de cette affaire.", "points": [{"position": 1, "label": "Informer que le logement est désormais sécurisé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Fin de l''attente et début des constatations.", "groups": [{"position": 1, "keywords": ["logement sécurisé", "attente terminée", "constatations débutées"]}]}, {"position": 2, "label": "Les autoriser à entrer en les accompagnant pour canaliser leurs déplacements", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas compromettre les traces encore présentes.", "groups": [{"position": 1, "keywords": ["entrée accompagnée", "déplacements canalisés", "traces préservées"]}]}, {"position": 3, "label": "Recueillir leurs premières observations sur les objets disparus", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Informations précieuses pour orienter les constatations.", "groups": [{"position": 1, "keywords": ["observations recueillies", "objets disparus", "constatations orientées"]}]}, {"position": 4, "label": "Informer de la nécessité d''un inventaire précis pour la suite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suite du traitement de cette affaire.", "groups": [{"position": 1, "keywords": ["inventaire précis", "suites informées", "traitement de l''affaire"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-tentative-cambriolage-voisin-vigilant', '{"slug": "biens-tentative-cambriolage-voisin-vigilant", "title": "Le voisin a fait fuir deux individus et les a photographiés", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 15 heures. Un riverain vous accueille avec une certaine fierté, expliquant avoir surpris deux individus en train de forcer la porte d''entrée du pavillon voisin, les avoir mis en fuite en criant depuis sa fenêtre, et avoir eu le réflexe de les photographier avec son téléphone avant qu''ils ne disparaissent au coin de la rue. Cette tentative de cambriolage interrompue par la vigilance de ce voisin fournit des éléments potentiellement précieux pour l''enquête, notamment ces photographies prises dans l''urgence.\n\nCe riverain, visiblement satisfait de son intervention, exprime une certaine tentation de continuer à jouer un rôle actif dans la suite de cette affaire, cette énergie méritant d''être canalisée sans pour autant l''encourager à prendre des risques supplémentaires face à des individus potentiellement dangereux.\n\nCette situation, où la vigilance citoyenne a permis d''interrompre une infraction en cours, nécessite d''exploiter au mieux les éléments recueillis tout en évitant que cette réussite ne conduise ce riverain à s''exposer davantage lors d''une éventuelle prochaine occasion.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recueillez-vous et exploitez-vous les éléments fournis par ce voisin vigilant ?", "hint": "Les photographies et le témoignage de ce voisin constituent des éléments précieux qui doivent être recueillis avec méthode et rapidité.", "perfect": "Je recueille avec précision son témoignage sur le déroulement exact de cette tentative, notamment l''heure, les gestes observés et la description physique des deux individus.\n\nJe récupère les photographies qu''il a prises, cette preuve visuelle constituant un élément particulièrement précieux pour l''identification éventuelle de ces auteurs.\n\nJe consigne également la direction de fuite qu''il a pu observer, cette information pouvant orienter utilement les recherches immédiates dans le quartier.\n\nJe le remercie clairement pour sa vigilance, cette reconnaissance étant méritée sans pour autant l''encourager à répéter une telle prise de risque à l''avenir.", "points": [{"position": 1, "label": "Recueillir précisément son témoignage sur le déroulement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : heure, gestes et description physique.", "groups": [{"position": 1, "keywords": ["témoignage précis", "déroulement recueilli", "description physique"]}]}, {"position": 2, "label": "Récupérer les photographies comme élément précieux", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Preuve visuelle pour l''identification.", "groups": [{"position": 1, "keywords": ["photographies récupérées", "preuve visuelle", "identification facilitée"]}]}, {"position": 3, "label": "Consigner la direction de fuite observée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orienter les recherches immédiates.", "groups": [{"position": 1, "keywords": ["direction de fuite", "recherches orientées", "information consignée"]}]}, {"position": 4, "label": "Le remercier clairement pour sa vigilance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reconnaissance méritée sans encourager le risque.", "groups": [{"position": 1, "keywords": ["remerciement", "reconnaissance méritée", "sans encouragement au risque"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment canalisez-vous son énergie sans l''encourager à prendre des risques supplémentaires à l''avenir ?", "hint": "La satisfaction légitime de ce voisin doit être valorisée sans pour autant l''inciter à reproduire une intervention directe face à des individus potentiellement dangereux.", "perfect": "Je valorise son geste de vigilance sans pour autant l''encourager explicitement à intervenir directement lors d''une prochaine occasion similaire, cette nuance étant importante pour sa propre sécurité.\n\nJe lui explique clairement les risques qu''aurait pu comporter une confrontation directe avec ces individus, ce rappel étant nécessaire malgré l''issue favorable de cette intervention.\n\nJe l''oriente vers une posture d''observation et de signalement plutôt que d''intervention directe pour l''avenir, cette distinction lui permettant de continuer à être utile sans s''exposer physiquement.\n\nJe reste attentive à ne pas minimiser sa contribution par ce recadrage, son geste ayant été objectivement utile malgré les risques qu''il aurait pu comporter.", "points": [{"position": 1, "label": "Valoriser le geste sans encourager une intervention future", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : nuance importante pour sa sécurité.", "groups": [{"position": 1, "keywords": ["geste valorisé", "pas d''encouragement futur", "sécurité personnelle"]}]}, {"position": 2, "label": "Expliquer clairement les risques d''une confrontation directe", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rappel nécessaire malgré l''issue favorable.", "groups": [{"position": 1, "keywords": ["risques expliqués", "confrontation directe", "issue favorable"]}]}, {"position": 3, "label": "L''orienter vers l''observation et le signalement plutôt que l''intervention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rester utile sans s''exposer physiquement.", "groups": [{"position": 1, "keywords": ["observation et signalement", "sans exposition physique", "posture adaptée"]}]}, {"position": 4, "label": "Ne pas minimiser sa contribution par ce recadrage", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Geste objectivement utile malgré les risques.", "groups": [{"position": 1, "keywords": ["contribution non minimisée", "geste utile", "malgré les risques"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous la situation des propriétaires du pavillon visé par cette tentative interrompue ?", "hint": "Les propriétaires, absents ou présents, doivent être informés et rassurés sur cette tentative interrompue par la vigilance du voisin.", "perfect": "Je m''assure d''informer les propriétaires de ce pavillon de cette tentative de cambriolage, cette information leur étant due qu''ils soient présents ou non au moment des faits.\n\nJe procède aux constatations nécessaires sur la porte d''entrée endommagée, ces traces d''effraction constituant un élément matériel complémentaire au témoignage de ce voisin vigilant.\n\nJe les rassure sur l''interruption de cette tentative grâce à la vigilance de leur voisin, cette information positive pouvant atténuer l''inquiétude que cette découverte pourrait susciter.\n\nJe les conseille sur les mesures de sécurisation immédiate de leur porte endommagée, cette recommandation pratique complétant utilement le traitement de cette tentative interrompue.", "points": [{"position": 1, "label": "Informer les propriétaires de cette tentative de cambriolage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Information due qu''ils soient présents ou non.", "groups": [{"position": 1, "keywords": ["propriétaires informés", "tentative signalée", "information due"]}]}, {"position": 2, "label": "Procéder aux constatations sur la porte endommagée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Élément matériel complémentaire au témoignage.", "groups": [{"position": 1, "keywords": ["constatations effectuées", "porte endommagée", "élément matériel"]}]}, {"position": 3, "label": "Les rassurer sur l''interruption grâce à la vigilance du voisin", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Atténuer l''inquiétude par cette information positive.", "groups": [{"position": 1, "keywords": ["rassurance apportée", "vigilance du voisin", "inquiétude atténuée"]}]}, {"position": 4, "label": "Conseiller sur la sécurisation immédiate de la porte endommagée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Recommandation pratique complémentaire.", "groups": [{"position": 1, "keywords": ["conseil pratique", "sécurisation immédiate", "porte endommagée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-a-l-arrache-personne-agee', '{"slug": "biens-vol-a-l-arrache-personne-agee", "title": "Elle est tombée en tenant son sac et ne veut pas voir de médecin", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 11 heures. Une femme âgée vous appelle depuis la rue après avoir été victime d''un vol à l''arraché de son sac à main, précisant qu''elle est tombée durant l''agression en s''accrochant instinctivement à ses affaires, mais qu''elle refuse catégoriquement toute prise en charge médicale, insistant pour minimiser la chute et la douleur qu''elle ressent visiblement. Cette minimisation, fréquente chez les personnes âgées soucieuses de ne pas être perçues comme fragiles, masque potentiellement une blessure réelle qui nécessiterait une évaluation médicale sérieuse.\n\nCette victime, encore sous le choc de cette agression, semble davantage préoccupée par le récit des faits et la disparition de ses effets personnels que par son propre état physique, cette priorité inversée traduisant probablement un mécanisme de défense face à cette épreuve traumatisante.\n\nCette configuration nécessite de concilier le respect de son autonomie décisionnelle avec la vigilance nécessaire face à un refus de soins qui pourrait masquer une blessure sérieuse consécutive à cette chute provoquée par l''agression.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous évaluer médicalement cette victime malgré son refus initial catégorique ?", "hint": "Le refus de cette victime, aussi ferme soit-il, ne doit pas conduire à renoncer à s''assurer de son état physique réel après cette chute.", "perfect": "Je prends au sérieux ce refus tout en restant attentive aux signes physiques visibles qui pourraient témoigner d''une blessure plus sérieuse que celle qu''elle admet.\n\nJe l''interroge avec douceur sur les circonstances précises de sa chute et les zones de son corps qui ont pu être touchées, cette évaluation informelle pouvant révéler des éléments qu''elle minimiserait spontanément.\n\nJe lui explique posément pourquoi une évaluation médicale reste importante après une chute chez une personne de son âge, cette explication pouvant infléchir sa position sans la brusquer.\n\nJe sollicite, si les signes observés le justifient, l''intervention des services de secours malgré son refus initial, cette précaution étant nécessaire face à un risque de blessure qui ne serait pas immédiatement visible.", "points": [{"position": 1, "label": "Prendre au sérieux le refus tout en restant attentive aux signes physiques", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : signes témoignant d''une blessure sérieuse.", "groups": [{"position": 1, "keywords": ["refus pris au sérieux", "signes physiques observés", "blessure possible"]}]}, {"position": 2, "label": "L''interroger avec douceur sur les circonstances de la chute", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Évaluation informelle révélant des éléments minimisés.", "groups": [{"position": 1, "keywords": ["circonstances interrogées", "douceur", "éléments minimisés révélés"]}]}, {"position": 3, "label": "Expliquer posément l''importance d''une évaluation médicale après une chute", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Infléchir sa position sans la brusquer.", "groups": [{"position": 1, "keywords": ["explication posée", "importance de l''évaluation", "sans brusquer"]}]}, {"position": 4, "label": "Solliciter les secours si les signes observés le justifient", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Précaution face à une blessure non visible.", "groups": [{"position": 1, "keywords": ["secours sollicités", "précaution nécessaire", "blessure non visible"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les circonstances de ce vol à l''arraché tout en respectant son état émotionnel ?", "hint": "Le recueil du récit doit s''adapter au choc de cette victime, sans la brusquer par des questions trop pressantes.", "perfect": "Je l''écoute d''abord raconter les faits à son rythme, cette liberté de récit lui permettant de reprendre progressivement ses esprits après cette agression traumatisante.\n\nJe recueille avec précision les éléments descriptifs de l''auteur qu''elle a pu percevoir, notamment sa direction de fuite et son apparence générale, ces éléments restant précieux malgré le choc qu''elle traverse.\n\nJe reste attentive à ne pas la presser de questions si elle semble dépassée par l''émotion, cette adaptation du rythme de l''entretien restant nécessaire face à une victime encore sous le choc.\n\nJe recueille l''inventaire précis du contenu de son sac dérobé, cette information étant utile tant pour la procédure que pour d''éventuelles démarches administratives qu''elle devra entreprendre.", "points": [{"position": 1, "label": "L''écouter raconter les faits à son propre rythme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Liberté de récit permettant de reprendre ses esprits.", "groups": [{"position": 1, "keywords": ["écoute au rythme", "récit libre", "reprise des esprits"]}]}, {"position": 2, "label": "Recueillir précisément les éléments descriptifs de l''auteur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Direction de fuite et apparence malgré le choc.", "groups": [{"position": 1, "keywords": ["éléments descriptifs", "direction de fuite", "malgré le choc"]}]}, {"position": 3, "label": "Ne pas la presser de questions si elle semble dépassée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Adaptation du rythme de l''entretien.", "groups": [{"position": 1, "keywords": ["pas de pression", "rythme adapté", "victime sous le choc"]}]}, {"position": 4, "label": "Recueillir l''inventaire précis du contenu du sac dérobé", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour la procédure et les démarches administratives.", "groups": [{"position": 1, "keywords": ["inventaire du sac", "démarches administratives", "utile à la procédure"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite de la prise en charge de cette victime après ce recueil initial ?", "hint": "La prise en charge ne s''arrête pas au recueil des faits, un accompagnement adapté restant nécessaire pour cette personne âgée isolée après cette épreuve.", "perfect": "Je m''assure qu''elle ne reste pas seule immédiatement après cette agression, en sollicitant si possible la présence d''un proche pouvant l''accompagner dans les heures qui suivent.\n\nJe l''informe des démarches pratiques à effectuer rapidement, notamment l''opposition sur ses moyens de paiement si son sac en contenait, cette urgence pratique s''ajoutant au traumatisme vécu.\n\nJe reste attentive à son isolement éventuel, cette dimension sociale méritant d''être prise en compte au-delà du seul traitement de l''infraction dont elle a été victime.\n\nJe l''informe des suites de cette procédure et des associations d''aide aux victimes qui pourraient l''accompagner dans les suites de cette épreuve traumatisante.", "points": [{"position": 1, "label": "S''assurer qu''elle ne reste pas seule immédiatement après l''agression", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : présence d''un proche sollicitée.", "groups": [{"position": 1, "keywords": ["pas seule", "proche sollicité", "accompagnement immédiat"]}]}, {"position": 2, "label": "Informer des démarches pratiques urgentes comme l''opposition bancaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Urgence pratique s''ajoutant au traumatisme.", "groups": [{"position": 1, "keywords": ["démarches pratiques", "opposition bancaire", "urgence pratique"]}]}, {"position": 3, "label": "Rester attentive à son isolement éventuel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Dimension sociale au-delà du traitement de l''infraction.", "groups": [{"position": 1, "keywords": ["isolement pris en compte", "dimension sociale", "au-delà de l''infraction"]}]}, {"position": 4, "label": "Informer des associations d''aide aux victimes disponibles", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Accompagnement dans les suites de l''épreuve.", "groups": [{"position": 1, "keywords": ["associations d''aide", "accompagnement", "suites de l''épreuve"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-telephone-geolocalisation', '{"slug": "biens-vol-telephone-geolocalisation", "title": "L''application indique une adresse, il veut y aller lui-même", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 20 heures. Un homme se présente au commissariat pour signaler le vol de son téléphone quelques heures plus tôt, précisant avec insistance que l''application de géolocalisation associée à son appareil indique une adresse précise, et qu''il compte s''y rendre lui-même dès sa sortie du commissariat pour récupérer son bien. Cette détermination à mener sa propre investigation, portée par la conviction que cette technologie lui fournit une certitude absolue, comporte des risques réels qu''il ne semble pas mesurer.\n\nCette localisation, bien qu''elle puisse orienter utilement une enquête, reste par nature approximative et potentiellement trompeuse, cet outil ne garantissant ni la présence réelle du téléphone à cette adresse ni encore moins l''identité de son occupant au moment de l''intervention.\n\nCette situation nécessite de dissuader fermement cette victime de toute démarche personnelle, tout en exploitant utilement cette information de localisation dans un cadre qui reste celui d''une enquête menée par les services compétents.", "questions": [{"position": 1, "max_points": 5, "label": "Comment dissuadez-vous fermement cette victime de se rendre elle-même à cette adresse localisée ?", "hint": "La détermination de cette victime doit être fermement contrée, les risques d''une confrontation directe avec des inconnus potentiellement dangereux devant être clairement exposés.", "perfect": "Je lui explique fermement les risques réels qu''il encourrait en se rendant seul à cette adresse, une confrontation avec des inconnus potentiellement dangereux ne devant jamais être envisagée par une victime seule.\n\nJe lui rappelle que cette localisation reste approximative et ne garantit ni la présence de son téléphone ni l''identité de la personne qui occuperait ce lieu, cette incertitude technique renforçant le danger d''une démarche personnelle.\n\nJe reste attentive à sa détermination et n''hésite pas à répéter cette mise en garde si nécessaire, cette fermeté étant proportionnée au risque réel que comporterait une telle initiative.\n\nJe l''assure que cette information sera exploitée par les services compétents, cette garantie pouvant atténuer sa tentation d''agir seul en lui montrant que sa démarche ne sera pas ignorée.", "points": [{"position": 1, "label": "Expliquer fermement les risques d''une confrontation directe", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : confrontation avec des inconnus dangereux à éviter.", "groups": [{"position": 1, "keywords": ["risques expliqués fermement", "confrontation évitée", "inconnus dangereux"]}]}, {"position": 2, "label": "Rappeler que la localisation reste approximative et incertaine", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Incertitude technique renforçant le danger.", "groups": [{"position": 1, "keywords": ["localisation approximative", "incertitude technique", "danger renforcé"]}]}, {"position": 3, "label": "Répéter la mise en garde si sa détermination persiste", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Fermeté proportionnée au risque réel.", "groups": [{"position": 1, "keywords": ["mise en garde répétée", "fermeté proportionnée", "détermination persistante"]}]}, {"position": 4, "label": "Assurer que l''information sera exploitée par les services compétents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Garantie atténuant la tentation d''agir seul.", "groups": [{"position": 1, "keywords": ["information exploitée", "garantie donnée", "tentation atténuée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment exploitez-vous concrètement cette information de géolocalisation dans un cadre approprié ?", "hint": "Cette information peut être utile à l''enquête, à condition d''être exploitée par les canaux appropriés plutôt que par une démarche personnelle de la victime.", "perfect": "Je recueille avec précision cette information de localisation telle qu''elle apparaît sur l''application, en notant l''heure exacte et le degré de précision affiché par cet outil.\n\nJe transmets cette information aux services compétents pour une exploitation appropriée, cette transmission constituant le cadre légitime pour vérifier cette piste sans exposer la victime à un danger.\n\nJe reste attentive à ne pas surestimer la fiabilité de cette localisation dans mon propre traitement de cette affaire, cette prudence méthodologique restant nécessaire malgré l''apparente précision de l''outil.\n\nJe recueille également l''ensemble des circonstances du vol initial, ces éléments complémentaires pouvant enrichir utilement l''exploitation de cette piste technologique.", "points": [{"position": 1, "label": "Recueillir précisément l''information de localisation avec l''heure et la précision affichées", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information exploitable avec rigueur.", "groups": [{"position": 1, "keywords": ["localisation recueillie", "heure exacte", "degré de précision"]}]}, {"position": 2, "label": "Transmettre aux services compétents pour une exploitation appropriée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Cadre légitime sans exposer la victime.", "groups": [{"position": 1, "keywords": ["transmission appropriée", "cadre légitime", "victime non exposée"]}]}, {"position": 3, "label": "Ne pas surestimer la fiabilité de cette localisation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prudence méthodologique malgré l''apparente précision.", "groups": [{"position": 1, "keywords": ["prudence méthodologique", "fiabilité relative", "pas de surestimation"]}]}, {"position": 4, "label": "Recueillir les circonstances complémentaires du vol initial", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Enrichir l''exploitation de cette piste technologique.", "groups": [{"position": 1, "keywords": ["circonstances du vol", "éléments complémentaires", "piste enrichie"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous cette victime dans les suites pratiques de ce vol, au-delà de la seule question de la localisation ?", "hint": "Le vol de ce téléphone comporte des enjeux pratiques immédiats qui méritent d''être traités indépendamment de l''issue de la piste de localisation.", "perfect": "Je l''informe des démarches à entreprendre sans délai concernant la sécurisation de ses comptes et applications accessibles depuis ce téléphone, cette urgence pratique restant importante indépendamment de la piste de localisation.\n\nJe l''oriente vers son opérateur pour le blocage de la ligne, cette démarche complémentaire étant nécessaire pour limiter les conséquences pratiques de ce vol.\n\nJe reste attentive à recentrer son attention sur ces démarches concrètes plutôt que sur sa préoccupation exclusive pour cette localisation incertaine, cette réorientation étant utile pour sa propre protection.\n\nJe l''informe des suites de cette procédure de manière réaliste, sans lui laisser d''espoir disproportionné quant aux chances effectives de retrouver ce téléphone grâce à cette seule localisation.", "points": [{"position": 1, "label": "Informer des démarches urgentes de sécurisation des comptes", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : urgence pratique indépendante de la localisation.", "groups": [{"position": 1, "keywords": ["sécurisation des comptes", "démarches urgentes", "indépendant de la localisation"]}]}, {"position": 2, "label": "Orienter vers l''opérateur pour le blocage de la ligne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarche complémentaire limitant les conséquences.", "groups": [{"position": 1, "keywords": ["opérateur sollicité", "blocage de ligne", "conséquences limitées"]}]}, {"position": 3, "label": "Recentrer son attention sur ces démarches concrètes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réorientation utile pour sa propre protection.", "groups": [{"position": 1, "keywords": ["attention recentrée", "démarches concrètes", "protection personnelle"]}]}, {"position": 4, "label": "Informer de manière réaliste sur les chances effectives de retrouver le téléphone", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Pas d''espoir disproportionné sur la localisation.", "groups": [{"position": 1, "keywords": ["information réaliste", "pas d''espoir disproportionné", "chances effectives"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-dans-vehicule-serie', '{"slug": "biens-vol-dans-vehicule-serie", "title": "Sept véhicules fracturés sur le même niveau", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 8 heures. Vous êtes appelée dans un parking souterrain où sept véhicules garés sur le même niveau ont été fracturés durant la nuit, leurs propriétaires découvrant simultanément les dégâts et affluant progressivement vers votre équipage avec des questions et des réactions diverses. Cette multiplicité de victimes présentes en même temps sur un même lieu impose une organisation méthodique pour ne bâcler aucune des constatations individuelles nécessaires.\n\nCette série, réalisée visiblement par un même mode opératoire sur un nombre important de véhicules, présente un intérêt particulier pour l''enquête au-delà du seul traitement individuel de chaque vol constaté, cette dimension collective méritant d''être documentée avec soin.\n\nCette situation nécessite de gérer efficacement l''affluence simultanée de ces sept victimes, en assurant à chacune un traitement rigoureux de sa situation particulière tout en tirant parti de la vision d''ensemble que permet cette série sur un même site.", "questions": [{"position": 1, "max_points": 5, "label": "Comment organisez-vous la prise en charge de ces sept victimes présentes simultanément sans bâcler aucune constatation ?", "hint": "L''affluence simultanée de plusieurs victimes nécessite une organisation méthodique pour garantir un traitement rigoureux de chaque situation individuelle.", "perfect": "J''établis un ordre de traitement clair pour ces sept victimes, cette organisation permettant de gérer l''affluence sans que l''attente ne génère de frustration disproportionnée chez celles qui patientent.\n\nJe consacre à chaque véhicule le temps nécessaire pour des constatations rigoureuses, cette qualité individuelle ne devant pas être sacrifiée à la rapidité que pourrait sembler imposer le nombre de victimes présentes.\n\nJe sollicite un renfort si le nombre de victimes dépasse ce qu''une seule équipe peut raisonnablement traiter avec la rigueur nécessaire, cette demande restant appropriée face à cette affluence exceptionnelle.\n\nJe communique clairement à l''ensemble des victimes présentes sur l''organisation mise en place, cette transparence collective facilitant l''acceptation de l''attente par chacune d''entre elles.", "points": [{"position": 1, "label": "Établir un ordre de traitement clair pour gérer l''affluence", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : organisation sans frustration disproportionnée.", "groups": [{"position": 1, "keywords": ["ordre de traitement", "affluence gérée", "frustration limitée"]}]}, {"position": 2, "label": "Consacrer à chaque véhicule le temps nécessaire pour des constatations rigoureuses", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Qualité individuelle non sacrifiée à la rapidité.", "groups": [{"position": 1, "keywords": ["temps nécessaire", "constatations rigoureuses", "qualité préservée"]}]}, {"position": 3, "label": "Solliciter un renfort si l''affluence dépasse les capacités d''une équipe", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Demande appropriée face à l''affluence exceptionnelle.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "capacités dépassées", "affluence exceptionnelle"]}]}, {"position": 4, "label": "Communiquer clairement sur l''organisation à l''ensemble des victimes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence collective facilitant l''attente.", "groups": [{"position": 1, "keywords": ["communication claire", "transparence collective", "attente facilitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment documentez-vous le mode opératoire commun à cette série pour enrichir la dimension collective de l''enquête ?", "hint": "Au-delà du traitement individuel, cette série mérite une documentation spécifique du mode opératoire commun qui pourrait orienter utilement l''enquête.", "perfect": "Je relève avec attention les similitudes entre les différentes effractions constatées, notamment la méthode de forçage employée et les éventuels éléments dérobés de même nature.\n\nJe consigne ces éléments de manière centralisée plutôt que dispersée entre sept dossiers distincts, cette approche collective facilitant l''exploitation de cette série par les services d''enquête.\n\nJe reste attentive aux éventuels indices matériels laissés sur place, comme des traces d''outils ou des débris, ces éléments techniques pouvant enrichir utilement la documentation de ce mode opératoire.\n\nJe recueille auprès des victimes tout élément qu''elles auraient pu observer avant leur départ, comme la présence de véhicules ou d''individus suspects, cette information collective pouvant orienter les recherches.", "points": [{"position": 1, "label": "Relever les similitudes entre les différentes effractions", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : méthode de forçage et éléments dérobés communs.", "groups": [{"position": 1, "keywords": ["similitudes relevées", "méthode de forçage", "éléments communs"]}]}, {"position": 2, "label": "Consigner ces éléments de manière centralisée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche collective facilitant l''exploitation.", "groups": [{"position": 1, "keywords": ["consignation centralisée", "approche collective", "exploitation facilitée"]}]}, {"position": 3, "label": "Rester attentive aux indices matériels laissés sur place", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traces d''outils ou débris enrichissant la documentation.", "groups": [{"position": 1, "keywords": ["indices matériels", "traces d''outils", "documentation enrichie"]}]}, {"position": 4, "label": "Recueillir les observations des victimes sur des éléments suspects", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information collective orientant les recherches.", "groups": [{"position": 1, "keywords": ["observations recueillies", "éléments suspects", "recherches orientées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous les réactions diverses de ces victimes, certaines plus affectées ou impatientes que d''autres ?", "hint": "Face à une affluence de victimes aux réactions variées, un accueil individualisé reste nécessaire malgré la gestion collective de cette série.", "perfect": "Je reste attentive aux réactions différenciées de chacune de ces victimes, certaines pouvant être particulièrement affectées par la perte d''objets de valeur sentimentale au-delà du seul préjudice matériel.\n\nJe m''adapte à l''impatience de certaines victimes sans pour autant sacrifier la qualité du traitement réservé à celles qui patientent plus calmement, cet équilibre restant nécessaire dans cette gestion collective.\n\nJe reste factuelle et rassurante face aux inquiétudes exprimées sur la suite de cette procédure, cette posture professionnelle restant appropriée malgré l''affluence et la pression temporelle.\n\nJe m''assure qu''aucune victime ne reparte sans avoir pu exprimer l''ensemble de ses observations, cette vérification finale garantissant l''équité du traitement malgré la gestion simultanée de ces sept situations.", "points": [{"position": 1, "label": "Rester attentive aux réactions différenciées de chaque victime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : valeur sentimentale au-delà du préjudice matériel.", "groups": [{"position": 1, "keywords": ["réactions différenciées", "valeur sentimentale", "préjudice au-delà du matériel"]}]}, {"position": 2, "label": "S''adapter à l''impatience sans sacrifier la qualité pour les autres", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Équilibre nécessaire dans la gestion collective.", "groups": [{"position": 1, "keywords": ["adaptation à l''impatience", "qualité préservée", "équilibre nécessaire"]}]}, {"position": 3, "label": "Rester factuelle et rassurante face aux inquiétudes exprimées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Posture professionnelle malgré l''affluence.", "groups": [{"position": 1, "keywords": ["posture factuelle", "rassurance apportée", "malgré l''affluence"]}]}, {"position": 4, "label": "S''assurer qu''aucune victime ne reparte sans avoir pu s''exprimer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vérification finale garantissant l''équité.", "groups": [{"position": 1, "keywords": ["vérification finale", "équité du traitement", "expression garantie"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-de-vehicule-restitution', '{"slug": "biens-vol-de-vehicule-restitution", "title": "Le véhicule est retrouvé mais il n''est plus à personne", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 14 heures. Vous êtes appelée pour un véhicule stationné en double file depuis plusieurs jours dans une rue, dont la vérification du numéro d''immatriculation révèle qu''il correspond à un signalement de vol effectué plusieurs semaines auparavant, ce véhicule ayant visiblement été abandonné après usage par des personnes qui ne sont pas ses propriétaires légitimes. Cette découverte, si elle constitue une bonne nouvelle pour le propriétaire qui pourra récupérer son bien, nécessite une gestion méthodique qui ne se précipite pas vers la seule restitution immédiate.\n\nCe véhicule retrouvé peut en effet comporter des traces exploitables pour l''enquête relative à ce vol, ces éléments matériels risquant d''être définitivement perdus si le véhicule était restitué sans examen préalable à son propriétaire légitime, aussi impatient soit-il de récupérer son bien.\n\nCette situation impose de concilier la légitime attente de ce propriétaire de recouvrer son véhicule avec la nécessité de préserver ces éléments de preuve avant toute restitution, cet équilibre nécessitant une communication claire sur les raisons de ce délai supplémentaire.", "questions": [{"position": 1, "max_points": 5, "label": "Comment procédez-vous pour préserver les traces exploitables avant toute restitution de ce véhicule ?", "hint": "La préservation des traces doit primer sur l''empressement à restituer ce véhicule, aussi légitime soit l''attente du propriétaire.", "perfect": "Je m''abstiens de toute manipulation excessive du véhicule avant qu''un examen technique approprié n''ait pu être réalisé, cette précaution étant nécessaire pour préserver l''intégrité des traces potentiellement présentes.\n\nJe fais procéder aux constatations et prélèvements nécessaires par les services compétents avant d''envisager toute restitution, cette étape technique restant prioritaire malgré le délai supplémentaire qu''elle impose.\n\nJe reste attentive à documenter précisément l''état du véhicule tel que je le découvre, cette description immédiate pouvant compléter utilement les constatations techniques ultérieures.\n\nJe sécurise le véhicule en l''état dans l''attente de ces vérifications, cette mesure conservatoire évitant toute dégradation ou disparition supplémentaire d''éléments exploitables.", "points": [{"position": 1, "label": "S''abstenir de toute manipulation excessive avant examen technique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : préserver l''intégrité des traces potentielles.", "groups": [{"position": 1, "keywords": ["pas de manipulation excessive", "intégrité préservée", "traces potentielles"]}]}, {"position": 2, "label": "Faire procéder aux constatations avant toute restitution", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Étape technique prioritaire malgré le délai.", "groups": [{"position": 1, "keywords": ["constatations préalables", "étape prioritaire", "délai nécessaire"]}]}, {"position": 3, "label": "Documenter précisément l''état du véhicule dès la découverte", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Description immédiate complétant les constatations.", "groups": [{"position": 1, "keywords": ["état documenté", "description immédiate", "constatations complétées"]}]}, {"position": 4, "label": "Sécuriser le véhicule en l''état dans l''attente des vérifications", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mesure conservatoire évitant toute dégradation.", "groups": [{"position": 1, "keywords": ["véhicule sécurisé", "mesure conservatoire", "dégradation évitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment communiquez-vous avec le propriétaire sur ce délai supplémentaire avant restitution ?", "hint": "Le propriétaire impatient de récupérer son bien doit comprendre les raisons de ce délai, cette communication devant rester claire et transparente.", "perfect": "Je l''informe rapidement que son véhicule a été retrouvé, cette bonne nouvelle méritant d''être communiquée sans délai malgré le processus qui doit encore se dérouler avant la restitution effective.\n\nJe lui explique clairement pourquoi ce véhicule ne peut pas lui être restitué immédiatement, la nécessité de préserver les traces exploitables constituant une explication légitime de ce délai supplémentaire.\n\nJe reste attentive à sa frustration bien compréhensible face à ce délai, cette écoute empathique ne devant pas pour autant me conduire à précipiter une restitution prématurée.\n\nJe lui donne une estimation aussi précise que possible du délai avant restitution, cette information concrète lui permettant de mieux anticiper la suite de cette procédure.", "points": [{"position": 1, "label": "L''informer rapidement que son véhicule a été retrouvé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : bonne nouvelle communiquée sans délai.", "groups": [{"position": 1, "keywords": ["information rapide", "véhicule retrouvé", "bonne nouvelle"]}]}, {"position": 2, "label": "Expliquer clairement pourquoi la restitution n''est pas immédiate", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Nécessité de préserver les traces expliquée.", "groups": [{"position": 1, "keywords": ["explication claire", "traces à préserver", "délai justifié"]}]}, {"position": 3, "label": "Rester attentive à sa frustration sans précipiter la restitution", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Écoute empathique sans restitution prématurée.", "groups": [{"position": 1, "keywords": ["frustration entendue", "écoute empathique", "pas de précipitation"]}]}, {"position": 4, "label": "Donner une estimation du délai avant restitution", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information concrète pour anticiper la suite.", "groups": [{"position": 1, "keywords": ["délai estimé", "information concrète", "anticipation facilitée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment exploitez-vous cette découverte pour enrichir l''enquête relative au vol initial ?", "hint": "Ce véhicule retrouvé peut fournir des éléments précieux sur les circonstances de son usage après le vol, au-delà de la seule question de sa restitution.", "perfect": "Je consigne avec précision le lieu et les circonstances de la découverte de ce véhicule, ces éléments géographiques et temporels pouvant orienter utilement l''enquête sur son usage depuis le vol.\n\nJe recherche les éléments matériels qui pourraient avoir été laissés à l''intérieur du véhicule, ces traces pouvant révéler des informations sur l''identité ou les habitudes des personnes qui l''ont utilisé.\n\nJe transmets l''ensemble de ces éléments aux services en charge de l''enquête initiale sur ce vol, cette transmission permettant de relier utilement cette découverte à l''enquête déjà ouverte.\n\nJe reste attentive à ne pas considérer cette découverte comme clôturant définitivement le dossier, cette étape ne constituant qu''un élément complémentaire dans la recherche des auteurs du vol initial.", "points": [{"position": 1, "label": "Consigner précisément le lieu et les circonstances de la découverte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments orientant l''enquête sur l''usage du véhicule.", "groups": [{"position": 1, "keywords": ["lieu consigné", "circonstances de découverte", "enquête orientée"]}]}, {"position": 2, "label": "Rechercher les éléments matériels laissés à l''intérieur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traces révélant l''identité ou les habitudes des utilisateurs.", "groups": [{"position": 1, "keywords": ["éléments matériels", "traces révélatrices", "identité des utilisateurs"]}]}, {"position": 3, "label": "Transmettre aux services en charge de l''enquête initiale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Relier la découverte à l''enquête déjà ouverte.", "groups": [{"position": 1, "keywords": ["transmission aux services", "enquête reliée", "dossier initial"]}]}, {"position": 4, "label": "Ne pas considérer cette découverte comme clôturant le dossier", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Élément complémentaire dans la recherche des auteurs.", "groups": [{"position": 1, "keywords": ["dossier non clôturé", "élément complémentaire", "recherche des auteurs"]}]}]}]}'::jsonb);